Bash(python3 - << 'EOF'
import json

with open\('/tmp/cg_openapi.json'\) as f:
    doc = json.load\(f\)

schemas = doc.get\('components', {}\).get\('schemas', {}\)
paths = doc.get\('paths', {}\)

# 找所有 allOf 中 override properties 为空（data 字段没有被正确 override）的组合类型
# 表现：allOf[1] 里 properties 缺失或为 {}
suspect = []
for name, schema in schemas.items\(\):
    allof = schema.get\('allOf', []\)
    if len\(allof\) >= 2:
        override = allof[1]
        props = override.get\('properties', {}\)
        if not props:
            suspect.append\(name\)

print\(f"allOf schemas with empty override properties \({len\(suspect\)}\):"\)
for k in suspect[:20]:
    print\(f"  {k}"\)

# 检查 response 中内联 allOf schema 的情况（不在 components 中，直接内联）
inline_empty = []
def check_schema\(s, loc\):
    if s is None:
        return
    allof = s.get\('allOf', []\)
    if len\(allof\) >= 2:
        override = allof[1]
        props = override.get\('properties', {}\)
        if not props:
            inline_empty.append\(loc\)

for path, pi in paths.items\(\):
    for method in ['get','post','put','delete','patch']:
        op = pi.get\(method\)
        if not op:
            continue
        for code, resp in \(op.get\('responses'\) or {}\).items\(\):
            for ct, mt in \(resp.get\('content'\) or {}\).items\(\):
                check_schema\(mt.get\('schema'\), f"{method.upper\(\)} {path} {code}"\)

print\(f"\\ninline allOf with empty override \({len\(inline_empty\)}\):"\)
for x in inline_empty[:30]:
    print\(f"  {x}"\)
EOF)
